50	const rateLimitMap = new Map();
51	const RATE_LIMIT_WINDOW = 60_000; // 1 minute
52	const RATE_LIMITS = {
53	  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
54	  write: 60,   // file writes, creates, deletes — 60/min
55	  read: 200,   // reads, listings — 200/min
