58	function rateLimit(tier) {
59	  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
60	  return (req, res, next) => {
61	    const key = `${tier}:${req.ip}`;
62	    const now = Date.now();
63	    let entry = rateLimitMap.get(key);
64	    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
65	      entry = { start: now, count: 0 };
66	      rateLimitMap.set(key, entry);
67	    }
68	    entry.count++;
69	    if (entry.count > max) {
70	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
71	    }
72	    next();
73	  };
74	}
